python3 -c "
import pathlib,re
want=('## 上流指針','### 本章での適用','### 確定判断ごとの原則採否')
for p in sorted(pathlib.Path('system-spec').glob('*.md')):
  if p.name in ('index.md','00-requirements-definition.md'): continue
  lines=p.read_text().splitlines(); out=[]; on=False
  for l in lines:
    if l.startswith('#'):
      on=any(l.startswith(w) for w in want)
    if on: out.append(l)
  print('=====',p.name); print('\n'.join(out))
  print('記録経路' in p.read_text(), 'unrecorded' in p.read_text(), 'legacy_backfill' in p.read_text())
"
